func stepsClass(s int64) string {
	if s >= 10000 {
		return "steps-good"
	}
	return "steps-low"
}

func sleepClass(h float64) string {
	if h >= 7 {
		return "sleep-good"
	}
	if h >= 5.5 {
		return "sleep-ok"
	}
	return "sleep-low"
}

func calorieClass(cal, budget float64) string {
	if budget <= 0 {
		return "cal-good"
	}
	if cal > budget*1.1 {
		return "cal-over"
	}
	if cal < budget*0.6 {
		return "cal-low"
	}
	return "cal-good"
}

